def comb_sort(nums):
    if len(nums) <= 1:
        return nums.copy()

    n = len(nums)
    gap = n
    sorted_flag = False

    while not sorted_flag:
        gap = max(1, int(gap / 1.3))  # Reduce gap by a factor of 1.3
        sorted_flag = True
        for i in range(n - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                sorted_flag = False
    return nums
```

