    # This will store the first index at which each difference occurs
    diff_map = {0: -1}
    max_diff = 0
    current_diff = 0  # difference between 0s and 1s (0s - 1s)

    for i, char in enumerate(string):
        if char == '0':
            current_diff += 1
        else:
            current_diff -= 1

