def find_combinations(test_list):
    result = []
    for i in range(len(test_list)):
        for j in range(len(test_list)):
            tuple1 = test_list[i]
            tuple2 = test_list[j]
            # Ensure we're not adding the same pair twice in a confusing order
            if (i == j):
                # If same tuple, just add the two elements in order
                result.append((tuple1[0] + tuple2[0], tuple1[1] + tuple2[1]))
            else:
                # Different tuples, add all four combinations of elements
                combinations = [
                    (tuple1[0] + tuple2[0], tuple1[1] + tuple2[1]),
                    (tuple1[0] + tuple2[1], tuple1[1] + tuple2[0])
                ]
                result.extend(combinations)
    return result
